#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum OpType {
    Add,
    Multiply,
    LogicalAnd,
    LogicalOr,
}

/// Returns the identity element for the selected operation if it exists.
///
/// Semantics:
/// - Add: integer addition -> identity is 0
/// - Multiply: integer multiplication -> identity is 1
/// - LogicalAnd / LogicalOr: operands are coerced to bool (nonzero=true),
///   result is 1 or 0 -> no integer identity exists for all integers x.
fn ufunc_identity(op: OpType) -> Option<i8> {
    match op {
        OpType::Add => Some(0i8),
        OpType::Multiply => Some(1i8),
        OpType::LogicalAnd => None,
        OpType::LogicalOr => None,
    }
}

fn main() {
    // Example usage
    assert_eq!(ufunc_identity(OpType::Add), Some(0));
    assert_eq!(ufunc_identity(OpType::Multiply), Some(1));
    assert_eq!(ufunc_identity(OpType::LogicalAnd), None);
    assert_eq!(ufunc_identity(OpType::LogicalOr), None);
}